// Generates src/icons.ts from icons/icons.json: only the listed icons, taken from Tabler Icons
// (MIT), whose licence is copied next to the list. The Tabler package is a build-time dependency.
//
//   node scripts/build-icons.mjs          write
//   node scripts/build-icons.mjs --check  fail if the generated files are stale

import { readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const require = createRequire(join(root, "package.json"));
const tablerDir = dirname(require.resolve("@tabler/icons/package.json"));
const tabler = JSON.parse(readFileSync(join(tablerDir, "tabler-nodes-outline.json"), "utf8"));
const version = JSON.parse(readFileSync(join(tablerDir, "package.json"), "utf8")).version;
const list = JSON.parse(readFileSync(join(root, "icons/icons.json"), "utf8")).icons;

const seen = new Set();
const entries = list.map((icon) => {
  if (seen.has(icon.name)) throw new Error(`Icon name "${icon.name}" is listed twice`);
  seen.add(icon.name);
  const nodes = tabler[icon.tabler];
  if (!nodes) throw new Error(`Tabler has no outline icon "${icon.tabler}" (for "${icon.name}")`);
  if (!icon.usage) throw new Error(`Icon "${icon.name}" needs a usage note`);
  const shapes = nodes.map(([tag, attrs]) => [
    tag,
    Object.fromEntries(Object.entries(attrs).filter(([key]) => key !== "key")),
  ]);
  return `  /** ${icon.usage}. Tabler: ${icon.tabler}. */\n  ${JSON.stringify(icon.name)}: ${JSON.stringify(shapes)},`;
});

const ts = `// Generated by scripts/build-icons.mjs from icons/icons.json. Do not edit.
// Shapes from Tabler Icons ${version} (outline), MIT licence: see icons/LICENSE-tabler.txt.
// Each icon is drawn on a 24-unit grid; .r-icon renders it at 16px with a 1.5px line.

export type IconShape = [tag: string, attributes: Record<string, string>];

export const ICONS = {
${entries.join("\n")}
} satisfies Record<string, IconShape[]>;

export type IconName = keyof typeof ICONS;
`;
const licence = readFileSync(join(tablerDir, "LICENSE"), "utf8");

const outputs = [
  [join(root, "src/icons.ts"), ts],
  [join(root, "icons/LICENSE-tabler.txt"), licence],
];
if (process.argv.includes("--check")) {
  const stale = outputs.filter(([path, text]) => {
    try {
      return readFileSync(path, "utf8") !== text;
    } catch {
      return true;
    }
  });
  if (stale.length > 0) {
    console.error(
      `Icons are out of date; run node packages/ui/scripts/build-icons.mjs (${stale.map(([p]) => p).join(", ")})`,
    );
    process.exit(1);
  }
  console.log("Icons are up to date.");
} else {
  for (const [path, text] of outputs) writeFileSync(path, text);
  console.log(`Wrote ${list.length} icons to src/icons.ts`);
}
